function normalizeFieldValue(type, value) {
  if (value === null || value === undefined || value === "") return null;

  switch (type) {
    case 2: // number
      return isNaN(value) ? null : Number(value);

    case 5: // datetime
      const d = new Date(value);
      return isNaN(d.getTime()) ? null : d.getTime();

    case 3: // boolean
      return Boolean(value);

    case 4: // json
      try {
        return typeof value === "object" ? JSON.stringify(value) : value;
      } catch {
        return null;
      }

    default: // text
      if (typeof value === "object") return JSON.stringify(value);
      return String(value);
  }
}

function mapFieldsToLark(item, fieldMap, typeMap) {
  const fields = {};

  for (const [key, label] of Object.entries(fieldMap)) {
    const value = item[key];

    if (value !== undefined && value !== null) {
      const type = typeMap[key] ?? 1; // default text
      fields[label] = normalizeFieldValue(type, value);
    }
  }

  return { fields };
}

function utcTimestampToVn(ts) {
  const d = new Date(ts * 1000);

  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mi = String(d.getUTCMinutes()).padStart(2, "0");
  const ss = String(d.getUTCSeconds()).padStart(2, "0");

  return `${yyyy}/${mm}/${dd} ${hh}:${mi}:${ss}`;
}

function utcTimestampToUtcISO(ts) {
  if (!ts) return null;
  return new Date(ts * 1000).toISOString(); 
}

