const now = new Date();
const timeZone = "Asia/Ho_Chi_Minh";

// Lấy ngày hiện tại tại Việt Nam, không phụ thuộc timezone của server n8n.
const dateParts = Object.fromEntries(
  new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  })
    .formatToParts(now)
    .filter((part) => part.type !== "literal")
    .map((part) => [part.type, Number(part.value)]),
);

const { year, month, day } = dateParts;

// Get Statements chia ngày theo UTC. TikTok khuyến nghị dùng một thời điểm
// trong ngày nhưng không dùng đúng 00:00 UTC, nên cộng 1 giây.
const from = Math.floor(Date.UTC(year, month - 1, day, 0, 0, 1) / 1000);
const to = Math.floor(Date.UTC(year, month - 1, day + 1, 0, 0, 1) / 1000);

return [{
  json: {
    current_month: month,
    statement_time_ge: from,
    statement_time_lt: to,
    from_utc: new Date(from * 1000).toISOString(),
    to_utc: new Date(to * 1000).toISOString(),
  },
}];

